package merge

import (
	"reflect"
	"testing"
)

type gsrWitnessLister []string

func (l gsrWitnessLister) List() []string {
	return []string(l)
}

func TestGSRWitness(t *testing.T) {
	a := gsrWitnessLister{"a"}
	b := gsrWitnessLister{"a"}
	got := Merge(a, b)
	want := []string{"a"}

	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Merge(a, b) = %v, want %v", got, want)
	}
}

