package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	calls int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.calls++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessStore{}
	_ = Save(ctx, store, "test-id", "val-a", "val-b")

	if store.calls >= 2 {
		t.Fatalf("Save with cancelled context made %d Put calls, want < 2", store.calls)
	}
}

