package saver

import (
	"context"
	"testing"
)

type gsrWitnessCompliantStore struct {
	puts int
}

func (s *gsrWitnessCompliantStore) Put(ctx context.Context, key, value string) error {
	s.puts++
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessCompliantStore{}
	err := Save(ctx, store, "id", "a", "b")

	if store.puts != 1 {
		t.Fatalf("Save() made %d Put calls, want 1", store.puts)
	}
	if err != context.Canceled {
		t.Fatalf("Save() error = %v, want %v", err, context.Canceled)
	}
}

