package upload

import (
	"errors"
	"testing"
)

type gsrFailWriter struct {
	flushed bool
}

func (w *gsrFailWriter) Write(string) error {
	return errors.New("simulated write error")
}

func (w *gsrFailWriter) Flush() error {
	w.flushed = true
	return nil
}

func TestGSRWitness(t *testing.T) {
	w := &gsrFailWriter{}
	_ = Upload(w, []string{"part1"})
	if w.flushed {
		t.Fatalf("Upload() called Flush after Write error, want no Flush call")
	}
}

